const channels = [
  'betting_job',
  'robotaua_now_remote',
  'opento_igaming',
  'iGaming_work'
];

const state = $getWorkflowStaticData('global');
if (!state.seenIds) state.seenIds = [];

const keywords = [
  'n8n', 'automation', 'автоматизац', 'ai agent', 'rag',
  'support', 'саппорт', 'підтримк', 'helpdesk', 'customer care',
  'vip', 'account manager', 'retention', 'crm',
  'оператор чата', 'оператор колл', 'супроводу клієнтів',
  'frontend', 'react', 'web developer', 'помічник керівника'
];

const stopWords = [
  'affiliate', 'аффилиат', 'media buyer', 'медиабайер', 'арбитраж',
  'nutra', 'нутра', 'seo', 'link builder', 'бухгалтер', 'водіння',
  'комбікорм', 'холодным звонкам', 'cold calls', 'influence',
  'взыскания', 'bas, baf', 'киргизского'
];

const results = [];

try {
  const n8nData = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://community.n8n.io/c/jobs/13.json',
    json: true
  });
  const topics = (n8nData.topic_list?.topics || []).filter(t => !t.pinned).slice(0, 4);
  for (const t of topics) {
    const postId = `n8n_${t.id}`;
    if (state.seenIds.includes(postId)) continue;
    if (t.title.toLowerCase().includes('referral')) continue;
    state.seenIds.push(postId);
    results.push({
      json: {
        channel: 'n8n_community_jobs',
        post_id: postId,
        url: `https://community.n8n.io/t/${t.slug}/${t.id}`,
        text: `n8n Job Post: ${t.title}\nTags: ${(t.tags || []).join(', ')}`
      }
    });
    if (results.length >= 2) break;
  }
} catch (e) {}

for (const ch of channels) {
  const html = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://t.me/s/${ch}`,
    headers: { 'User-Agent': 'Mozilla/5.0' }
  });

  const blocks = html.split('tgme_widget_message_wrap').slice(-15);

  for (const block of blocks) {
    const linkMatch = block.match(/data-post="([^"]+)"/);
    const textMatch = block.match(/<div class="tgme_widget_message_text[^>]*>([\s\S]*?)<\/div>/);
    if (!linkMatch || !textMatch) continue;

    const postId = linkMatch[1];
    if (state.seenIds.includes(postId)) continue;

    const cleanText = textMatch[1]
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&#036;/g, '$')
      .replace(/&quot;/g, '"')
      .trim();

    if (cleanText.length < 60) continue;

    const lower = cleanText.toLowerCase();
    if (stopWords.some(w => lower.includes(w))) continue;
    if (!keywords.some(k => lower.includes(k))) continue;

    state.seenIds.push(postId);
    results.push({
      json: {
        channel: ch,
        post_id: postId,
        url: `https://t.me/${postId}`,
        text: cleanText.slice(0, 1500)
      }
    });

    if (results.length >= 5) break;
  }
  if (results.length >= 5) break;
}

state.seenIds = state.seenIds.slice(-400);
return results;

